"""
    value : OSC value
    OscRange:
    midiRange
    """
def convertValueToOSCRange(midiValue: Any, oscRange: Any, midiRange: Any) -> object {
    minOSC = oscRange[0];
    maxOSC = oscRange[1];
    minMidi = midiRange[0];
    maxMidi = midiRange[1];
    percent = ((midiValue - minMidi) / (maxMidi - minMidi)) * 100.0;
    oscVal = (((maxOSC - minOSC) * percent) / 100) + minOSC;
    return oscVal;
}

